<?php
declare(strict_types=1);
function uploadRoute(string $path,string $method): void {
 if($path==='/profile/avatar'&&$method==='POST') { $u=requireUser(); rateLimit('avatar:'.$u['id'],10,3600); $f=$_FILES['avatar']??null; if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>2097152||!is_uploaded_file($f['tmp_name'])) fail(422,'ارفع صورة JPEG أو PNG أو WebP بحجم لا يتجاوز 2MB'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']); if(!in_array($mime,['image/jpeg','image/png','image/webp'],true)) fail(422,'نوع الصورة غير مسموح'); $info=getimagesize($f['tmp_name']); if(!$info||$info[0]>4096||$info[1]>4096||$info[0]*$info[1]>12000000) fail(422,'أبعاد الصورة كبيرة أو غير صالحة'); $img=imagecreatefromstring(file_get_contents($f['tmp_name'])); if(!$img) fail(422,'الصورة غير صالحة'); $w=512;$h=512;$dest=imagecreatetruecolor($w,$h);$white=imagecolorallocate($dest,255,255,255);imagefill($dest,0,0,$white);$side=min($info[0],$info[1]);imagecopyresampled($dest,$img,0,0,(int)(($info[0]-$side)/2),(int)(($info[1]-$side)/2),512,512,$side,$side); $dir=__DIR__.'/storage/avatars';if(!is_dir($dir))mkdir($dir,0700,true);$name=bin2hex(random_bytes(20)).'.jpg';if(!imagejpeg($dest,$dir.'/'.$name,85))fail(500,'تعذر حفظ الصورة');imagedestroy($img);imagedestroy($dest);query('UPDATE users SET avatar=? WHERE id=?',[$name,$u['id']]);if($u['avatar']&&preg_match('/^[a-f0-9]{40}\.jpg$/D',$u['avatar']))@unlink($dir.'/'.$u['avatar']);respond(['user'=>currentUser()]); }
 if(preg_match('#^/avatars/([a-f0-9]{40}\.jpg)$#',$path,$m)&&$method==='GET') { $u=requireUser();if($u['avatar']!==$m[1]&&$u['role']!=='admin')fail(403,'الصورة خاصة بالحساب');$file=__DIR__.'/storage/avatars/'.$m[1];if(!is_file($file))fail(404,'الصورة غير موجودة');header('Content-Type: image/jpeg');header('Cache-Control: private, no-store');readfile($file);exit; }
}
